(function(root){
 'use strict';
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function hierarchy(projects){const divisions=new Map(),seen=new Set();let excluded=0;for(const p of projects){if(seen.has(p.id))continue;seen.add(p.id);if(!Number.isFinite(p.budget)||p.budget<0){excluded++;continue;}if(!divisions.has(p.sector))divisions.set(p.sector,{name:p.sector,value:0,children:[]});const d=divisions.get(p.sector);d.children.push({...p,value:p.budget});d.value+=p.budget;}const children=[...divisions.values()];return {name:'Vanguarda',value:children.reduce((s,d)=>s+d.value,0),children,excluded};}
 function arc(start,end,inner,outer){end=Math.min(end,start+Math.PI*2-.00001);const point=(r,a)=>[230+r*Math.sin(a),230-r*Math.cos(a)];const a=point(outer,start),b=point(outer,end),c=point(inner,end),d=point(inner,start);const large=end-start>Math.PI?1:0;return `M${a} A${outer},${outer} 0 ${large} 1 ${b} L${c} A${inner},${inner} 0 ${large} 0 ${d} Z`;}
 function mount(container,projects){let division=null,project=null;const tree=hierarchy(projects);const share=v=>tree.value>0?(v/tree.value*100).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':'—';const money=v=>v.toLocaleString('pt-BR',{maximumFractionDigits:2})+' R$ milhões';const colors=['var(--division-1)','var(--division-2)','var(--division-3)'];const divisionColor=name=>colors[(['Incorporações','Logística','Energia'].includes(name)?['Incorporações','Logística','Energia'].indexOf(name):tree.children.findIndex(d=>d.name===name))%colors.length];
 function render(focus=false){if(!container.isConnected)return;const groups=tree.children.filter(d=>!division||d.name===division).map(d=>({...d,children:d.children.filter(p=>!project||p.id===project)})).map(d=>({...d,value:d.children.reduce((s,p)=>s+p.value,0)}));const total=groups.reduce((s,d)=>s+d.value,0);let angle=0,paths='';const nodes=[];for(const d of groups){const start=angle,end=start+(total?d.value/total*Math.PI*2:0),color=divisionColor(d.name);if(d.value>0){const i=nodes.push({division:d.name,label:d.name,value:d.value})-1;paths+=`<path d="${arc(start,end,78,138)}" fill="${color}" tabindex="0" role="button" aria-describedby="sun-tooltip" data-node="${i}" aria-label="${esc(d.name)}: ${money(d.value)}, ${share(d.value)} do total filtrado. Explorar divisão"><title>${esc(d.name)} · ${money(d.value)} · ${share(d.value)} do total filtrado</title></path>`;}let childAngle=start;for(const p of d.children){const endChild=childAngle+(total?p.value/total*Math.PI*2:0);if(p.value>0){const i=nodes.push({division:d.name,project:p.id,label:p.name,value:p.value,status:p.status})-1;paths+=`<path d="${arc(childAngle,endChild,143,216)}" fill="${color}" fill-opacity="${.78+.18*(tree.children.find(v=>v.name===d.name).children.findIndex(v=>v.id===p.id)%2)}" tabindex="0" role="button" aria-describedby="sun-tooltip" data-node="${i}" aria-label="${esc(p.name)}: ${money(p.value)}, ${esc(p.status)}, ${share(p.value)} do total filtrado. Explorar projeto"><title>${esc(p.name)} · ${money(p.value)} · ${share(p.value)} do total filtrado · ${esc(p.status)}</title></path>`;}childAngle=endChild;}angle=end;}
 container.innerHTML=`<div class="card-head"><h2>Orçamento por divisão e projeto</h2><span class="tag">Sunburst · R$ milhões</span></div><p class="subtitle">Vanguarda → Divisão → Projeto · orçamento aprovado · base sintética.</p><div class="sun-toolbar"><nav class="sun-breadcrumb" aria-label="Navegação do Sunburst"><button class="button" data-level="root">Vanguarda</button>${division?`<span aria-hidden="true">›</span><button class="button" data-level="division">${esc(division)}</button>`:''}${project?`<span aria-hidden="true">›</span><span>${esc(projects.find(p=>p.id===project)?.name||project)}</span>`:''}</nav><button class="button" data-level="root" ${!division?'disabled':''}>Voltar ao total</button></div><div class="sun-layout"><div>${total?`<svg class="sunburst" viewBox="0 0 460 460" role="group" aria-label="Sunburst do orçamento, use Tab e Enter para explorar"><circle cx="230" cy="230" r="73" fill="var(--panel)"/>${paths}<text x="230" y="223" text-anchor="middle" fill="var(--text)" font-size="26" font-weight="600">${total.toLocaleString('pt-BR')}</text><text x="230" y="250" text-anchor="middle" fill="var(--text-muted)" font-size="14">R$ milhões</text></svg>`:'<p role="status">Nenhum orçamento positivo nesta seleção. Ajuste os filtros.</p>'}<p id="sun-tooltip" class="sun-tooltip glass-control" role="status" aria-live="polite">${money(total)} · ${share(total)} do total filtrado. Passe sobre um setor, use Tab ou clique para explorar.</p></div><div class="sun-legend glass-control"><h3>Divisões · total filtrado</h3>${tree.children.map((d,i)=>`<button class="button" data-division="${esc(d.name)}" aria-pressed="${division===d.name}"><i style="background:${divisionColor(d.name)}" aria-hidden="true"></i>${esc(d.name)} · ${money(d.value)}</button>`).join('')}<h3>Situação · consulte o tooltip ou a tabela</h3><p class="sun-positive">● Saudável</p><p class="sun-attention">▲ Atenção</p><p class="sun-critical">! Crítico</p><p>◇ Sem base</p><details class="sun-help"><summary>Como ler o gráfico</summary><p>Os anéis representam o mesmo orçamento em níveis diferentes e não devem ser somados. Riscos não têm orçamento próprio nesta base; a hierarquia termina no projeto.</p></details></div></div><p class="sun-note">${tree.excluded?tree.excluded+' projetos sem orçamento válido foram excluídos.':'Cada projeto é contado uma única vez no total.'}</p><details class="sun-table"><summary>Alternativa acessível em tabela</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Orçamento por divisão e projeto"><table><caption>Orçamento na seleção: ${money(total)}</caption><thead><tr><th>Divisão</th><th>Projeto</th><th>Situação</th><th>Orçamento (R$ milhões)</th><th>Participação no total filtrado</th></tr></thead><tbody>${groups.flatMap(d=>d.children.map(p=>`<tr><td>${esc(d.name)}</td><td><button class="project-link" data-project="${esc(p.id)}">${esc(p.name)}</button></td><td>${esc(p.status)}</td><td>${p.value.toLocaleString('pt-BR')}</td><td>${share(p.value)}</td></tr>`)).join('')||'<tr><td colspan="5">Nenhum projeto na seleção.</td></tr>'}</tbody><tfoot><tr><th colspan="3">Total</th><td>${total.toLocaleString('pt-BR')}</td><td>${share(total)}</td></tr></tfoot></table></div></details>`;
 const explore=node=>{division=node.division;project=node.project||null;render(true);};container.querySelectorAll('[data-node]').forEach(el=>{const node=nodes[Number(el.dataset.node)];const tooltip=()=>container.querySelector('.sun-tooltip').textContent=`${node.label} · ${money(node.value)} · ${share(node.value)} do total filtrado${node.status?' · '+node.status:''}`;el.onpointerenter=tooltip;el.onfocus=tooltip;el.onclick=()=>explore(node);el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();explore(node);}};});container.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(b.dataset.level==='root')division=null;project=null;render(true);});container.querySelectorAll('[data-division]').forEach(b=>b.onclick=()=>explore({division:b.dataset.division}));container.querySelectorAll('[data-project]').forEach(b=>{const p=projects.find(p=>p.id===b.dataset.project);b.onclick=()=>explore({division:p.sector,project:p.id});});if(focus)container.querySelector('[data-level="root"]').focus();}
 render();}
 const api={hierarchy,arc,mount};if(typeof module!=='undefined')module.exports=api;else root.VanguardaSunburst=api;
})(globalThis);
